async function loadUser(id: string | number): Promise<any> {
  const userRes = await fetch(`/api/users/${id}`);
  if (!userRes.ok) {
    throw new Error(`bad status ${userRes.status}`);
  }
  const user = await userRes.json();

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }
  const org = await orgRes.json();

  user.org = org;
  return user;
}

async function loadUsers(ids: (string | number)[]): Promise<any[]> {
  const results = await Promise.all(ids.map((id) => loadUser(id)));
  return results;
}

export { loadUser, loadUsers };
